fn solve(n: i8, m: i8) -> i8 {
    // Mixed groups require 1 unit of n and 2 units of m
    // max mixed groups = min(n, m/2)
    // After forming mixed groups, remaining m = m - 2 * mixed_groups
    // Then pure groups = remaining_m / 4
    //
    // Inputs: n, m are non-negative i8 (0..=127)
    // Output: total groups (mixed + pure), also i8 >= 0

    let mixed_groups = n.min(m / 2);
    let remaining_m = m - mixed_groups * 2;
    let pure_groups = remaining_m / 4;
    mixed_groups + pure_groups
}